-- =================== Embeddings (pgvector replaces sqlite_vec) ===================

-- paperless_vec (sqlite_vec virtual) → docs.paperless_chunks.embedding vector(384)
ALTER TABLE docs.paperless_chunks ADD COLUMN IF NOT EXISTS embedding vector(384);
CREATE INDEX IF NOT EXISTS idx_paperless_chunks_embedding ON docs.paperless_chunks USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- wa_vec (sqlite_vec virtual) → wa_messages.embedding vector(384)
ALTER TABLE wa_messages ADD COLUMN IF NOT EXISTS embedding vector(384);
CREATE INDEX IF NOT EXISTS idx_wa_messages_embedding ON wa_messages USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- vec_chunks (sqlite_vec virtual) → docs.document_chunks.embedding vector(384)
ALTER TABLE docs.document_chunks ADD COLUMN IF NOT EXISTS embedding vector(384);
CREATE INDEX IF NOT EXISTS idx_document_chunks_embedding ON docs.document_chunks USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

-- =================== Full-text search (tsvector replaces FTS5) ===================

-- email_messages_fts (FTS5) → email_messages.search_tsv tsvector (generated)
ALTER TABLE email_messages ADD COLUMN IF NOT EXISTS search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(subject, '') || ' ' || coalesce(from_name, '') || ' ' || coalesce(from_email, '') || ' ' || coalesce(snippet, '') || ' ' || coalesce(body_text, ''))) STORED;
CREATE INDEX IF NOT EXISTS idx_email_messages_search_tsv ON email_messages USING gin (search_tsv);

-- wa_messages_fts (FTS5) → wa_messages.search_tsv tsvector (generated)
ALTER TABLE wa_messages ADD COLUMN IF NOT EXISTS search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(text, '') || ' ' || coalesce(transcript, ''))) STORED;
CREATE INDEX IF NOT EXISTS idx_wa_messages_search_tsv ON wa_messages USING gin (search_tsv);

